#define main cm_reference_main
#include "cm_executive_reference.c"
#undef main
#include "inverse_trig_cases.h"
static agc_t baseline;
static void row(uint32_t n,uint16_t phase,uint16_t status){uint16_t w[2054];unsigned i;w[0]=(uint16_t)n;w[1]=(uint16_t)(n>>16);w[2]=phase;w[3]=status;w[4]=(uint16_t)machine.AllowInterrupt;w[5]=0;for(i=0;i<2048u;++i)w[i+6u]=(uint16_t)((unsigned)*memory(i)&(i<2u?0177777u:077777u));if(fwrite(w,sizeof w,1,stdout)!=1)exit(2);if(n<16u)fprintf(stderr,"n%u phase%u status%u PC%o Q%o A%o L%o MPAC%o/%o/%o\n",n,phase,status,get(5),get(2),get(0),get(1),get(0154),get(0155),get(0156));}
int main(int argc,char **argv){uint32_t n,limit=INVERSE_TRIG_CASES;enum inverse_trig_mission mission;if(argc<3)return 2;mission=(enum inverse_trig_mission)strtoul(argv[2],NULL,0);if(argc>3)limit=(uint32_t)strtoul(argv[3],NULL,0);memset(&machine,0,sizeof machine);if(agc_load_binfile(&machine,argv[1]))return 2;baseline=machine;InhibitAlarms=1;for(n=0;n<limit;++n){apollo_overlay_state m;agc_word irq;unsigned i,cycles,pc,phase=0;inverse_trig_input(&m,&irq,mission,n);machine=baseline;for(i=0;i<2048u;++i)*memory(i)=(int16_t)m.words[i];machine.AllowInterrupt=irq;for(cycles=0;cycles<10000u;++cycles){pc=get(5);if(!machine.PendFlag&&!machine.ExtraDelay){if(pc==(mission==INVERSE_TRIG_LM?06061u:06030u)){row(n,(uint16_t)phase,INVERSE_TRIG_DONE);break;}if(pc==(mission==INVERSE_TRIG_LM?03723u:03722u)){row(n,(uint16_t)phase,INVERSE_TRIG_ALARM_1301);break;}if(pc==03402u){row(n,(uint16_t)phase,INVERSE_TRIG_ALARM_1302);break;}if((phase==0u&&pc==03343u)||(phase==1u&&pc==(mission==INVERSE_TRIG_LM?03652u:03651u))||(phase==2u&&pc==(mission==INVERSE_TRIG_LM?03677u:03676u))){row(n,(uint16_t)phase,INVERSE_TRIG_OK);++phase;}}machine.ScalerCounter=0;if(agc_engine(&machine))return 2;}if(cycles==10000u){fprintf(stderr,"case%u timeoutPC%o phase%u\n",n,get(5),phase);return 2;}}return 0;}
